const termsBody={
  fr:['TAMUSNI est un média d’information édité par A&B TECHNOLOGIES. Les contenus sont fournis à titre informatif et ne constituent pas un conseil professionnel personnalisé.','Vous pouvez consulter librement les contenus publics. Un compte facultatif donne accès aux favoris et aux préférences personnelles. Vous devez fournir des informations exactes et protéger vos identifiants.','Il est interdit de détourner le service, de publier des contenus illicites ou de porter atteinte aux droits d’autrui. TAMUSNI peut suspendre un compte en cas d’abus.','Les sources externes sont citées lorsque disponibles. Les marques, images et contenus de tiers restent la propriété de leurs titulaires.','Vous pouvez supprimer votre compte depuis votre espace personnel. Pour toute question, contactez aetbconseil@gmail.com.'],
  en:['TAMUSNI is a news publication operated by A&B TECHNOLOGIES. Its content is provided for information and is not personalized professional advice.','Public content is freely accessible. An optional account provides saved stories and personal preferences. You must provide accurate information and protect your sign-in details.','You may not misuse the service, post unlawful content or infringe others’ rights. TAMUSNI may suspend an account for abuse.','External sources are cited where available. Third-party trademarks, images and content remain the property of their respective owners.','You may delete your account from your personal space. For questions, contact aetbconseil@gmail.com.'],
  ar:['تاموسني وسيلة إعلامية تصدرها A&B TECHNOLOGIES. محتواها لأغراض إعلامية ولا يشكل نصيحة مهنية شخصية.','يمكن الاطلاع على المحتوى العام بحرية. يتيح الحساب الاختياري حفظ المقالات والتفضيلات الشخصية. يجب تقديم معلومات صحيحة وحماية بيانات الدخول.','يُمنع إساءة استخدام الخدمة أو نشر محتوى غير قانوني أو انتهاك حقوق الآخرين. يجوز لتاموسني تعليق الحساب عند إساءة الاستخدام.','تُذكر المصادر الخارجية متى توفرت. تظل العلامات التجارية والصور ومحتويات الجهات الأخرى ملكاً لأصحابها.','يمكنك حذف حسابك من مساحتك الشخصية. للاستفسار، راسل aetbconseil@gmail.com.'],
  es:['TAMUSNI es un medio informativo editado por A&B TECHNOLOGIES. Su contenido es informativo y no constituye asesoramiento profesional personalizado.','El contenido público es de libre acceso. Una cuenta opcional permite guardar artículos y preferencias. Debes aportar datos correctos y proteger tus credenciales.','No se permite abusar del servicio, publicar contenido ilegal ni infringir derechos ajenos. TAMUSNI puede suspender una cuenta por abuso.','Las fuentes externas se citan cuando están disponibles. Las marcas, imágenes y contenidos de terceros pertenecen a sus titulares.','Puedes eliminar tu cuenta desde tu espacio personal. Para consultas, escribe a aetbconseil@gmail.com.'],
  pt:['A TAMUSNI é um meio informativo editado pela A&B TECHNOLOGIES. O conteúdo é informativo e não constitui aconselhamento profissional personalizado.','O conteúdo público é de acesso livre. Uma conta opcional permite guardar artigos e preferências. Deve fornecer dados corretos e proteger as credenciais.','É proibido abusar do serviço, publicar conteúdo ilegal ou infringir direitos de terceiros. A TAMUSNI pode suspender uma conta por abuso.','As fontes externas são citadas quando disponíveis. As marcas, imagens e conteúdos de terceiros pertencem aos seus titulares.','Pode eliminar a sua conta no seu espaço pessoal. Para dúvidas, escreva para aetbconseil@gmail.com.']
};
const esc = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const safeUrl = value => { try { if(/^\/(?!\/)/.test(String(value)))return esc(value);const url = new URL(value); return ['https:','http:'].includes(url.protocol) ? esc(url.href) : ''; } catch { return ''; } };
const normalizeSearch = value => String(value||'').normalize('NFKD').replace(/\p{M}/gu,'').toLocaleLowerCase().replace(/[^\p{L}\p{N}]+/gu,' ').trim();
const editDistance = (a,b) => { if(Math.abs(a.length-b.length)>2)return 3;let previous=Array.from({length:b.length+1},(_,i)=>i);for(let i=1;i<=a.length;i++){const next=[i];for(let j=1;j<=b.length;j++)next[j]=Math.min(next[j-1]+1,previous[j]+1,previous[j-1]+(a[i-1]===b[j-1]?0:1));previous=next;}return previous[b.length];};
const matchesSearch = (query,item,locale) => { const text=normalizeSearch([storyTitle(locale,item),storyExcerpt(locale,item),localizedCategory(locale,item.category),locale==='fr'?item.body:''].join(' '));const words=text.split(' ');return normalizeSearch(query).split(' ').every(term=>text.includes(term)||term.length>=4&&words.some(word=>Math.abs(word.length-term.length)<=2&&editDistance(term,word)<=2)); };
const icon = name => {
  const paths = { menu:'<path d="M4 7h16M4 12h16M4 17h16"/>', close:'<path d="M5 5l14 14M19 5L5 19"/>', arrow:'<path d="M12 19V5m-6 6 6-6 6 6"/>', search:'<circle cx="11" cy="11" r="7"/><path d="m16 16 5 5"/>', share:'<path d="M13 5l-2 2m2-2-2-2m2 2H8a5 5 0 0 0-5 5v2m18 3v4a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2v-4"/>', heart:'<path d="M20.8 8.6c0 4.2-8.8 10-8.8 10s-8.8-5.8-8.8-10a5 5 0 0 1 8.8-3.3 5 5 0 0 1 8.8 3.3Z"/>', bookmark:'<path d="M6 4h12v17l-6-4-6 4V4Z"/>', chevron:'<path d="m9 18 6-6-6-6"/>', eye:'<path d="M2 12s4-6 10-6 10 6 10 6-4 6-10 6-10-6-10-6Z"/><circle cx="12" cy="12" r="2.5"/>' };
  return `<svg viewBox="0 0 24 24" aria-hidden="true" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${paths[name] || paths.chevron}</svg>`;
};
const href = (locale, path = '') => `/${locale}/${path}`;
const articleHref = (locale, item) => href(locale, `articles/${encodeURIComponent(item.slug)}/`);
const localizedCategory=(locale,value)=>{const index=value==='Intelligence'?0:category.indexOf(value);return index<0?(extraCategoryNames[locale][value]||value):names[locale][index];};
const storyTitle=(locale,item)=>item.localized_title||(locale==='fr'?item.title:copy[locale].unavailable);
const storyExcerpt=(locale,item)=>item.localized_excerpt||(locale==='fr'?item.excerpt:'');
const date = (value, locale) => { try { return new Intl.DateTimeFormat(locale, { day:'numeric', month:'long', year:'numeric' }).format(new Date(value)); } catch { return ''; } };
const image = (item, className = '', eager = false) => item.cover_url && safeUrl(item.cover_url) ? `<img class="${className}" src="${safeUrl(item.cover_url)}" alt="" loading="${eager?'eager':'lazy'}" ${eager?'fetchpriority="high" ':''}decoding="async">` : `<span class="media-placeholder ${className}" aria-hidden="true">T</span>`;
const card = (locale, item) => `<article class="story-card reveal"><a class="story-media" href="${articleHref(locale,item)}" aria-label="${esc(storyTitle(locale,item))}">${image(item)}</a><div class="story-content"><span class="eyebrow">${esc(localizedCategory(locale,item.category))}</span><h3><a href="${articleHref(locale,item)}">${esc(storyTitle(locale,item))}</a></h3><p>${esc(storyExcerpt(locale,item))}</p><div class="story-meta"><time datetime="${esc(item.published_at)}">${date(item.published_at,locale)}</time><span>${Number(item.views || 0)} ${copy[locale].views}</span></div></div></article>`;
const cardList = (locale, items) => items.length ? items.map(item => card(locale,item)).join('') : `<p class="empty">${copy[locale].empty}</p>`;
const hreflangs = (basePath, origin) => locales.map(l => `<link rel="alternate" hreflang="${l}" href="${origin}/${l}/${basePath}">`).join('');
function layout({locale, title, description, path, main, session, origin, robots='index,follow', structuredData=[], imageUrl=''}) {
  const t=copy[locale]; const rtl=locale==='ar'; const brand=rtl?'tamusni-ar.png':'tamusni-latin.png';
  const labels=institutionLabels[locale];
  const nav=sections.map((section,i)=>`<a href="${href(locale,section+'/')}" ${path===section+'/'?'aria-current="page"':''}><span class="menu-number">0${i+1}</span>${names[locale][i]}${icon('chevron')}</a>`).join('');
  const current=path?path:''; const canonical=`${origin}/${locale}/${current}`;
  const socialImage=imageUrl?new URL(imageUrl,origin).href:`${origin}/brand/tamusni-latin.png`;
  const jsonLd=structuredData.map(data=>`<script type="application/ld+json">${JSON.stringify(data).replace(/</g,'\\u003c')}</script>`).join('');
  return `<!doctype html><html lang="${locale}" dir="${rtl?'rtl':'ltr'}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light dark"><meta name="google-adsense-account" content="ca-pub-6628181824999575"><meta name="robots" content="${robots}"><title>${esc(title)} — TAMUSNI</title><meta name="description" content="${esc(description)}"><meta property="og:type" content="${path.startsWith('articles/')?'article':'website'}"><meta property="og:site_name" content="TAMUSNI"><meta property="og:locale" content="${esc(locale)}"><meta property="og:title" content="${esc(title)} — TAMUSNI"><meta property="og:description" content="${esc(description)}"><meta property="og:url" content="${canonical}"><meta property="og:image" content="${esc(socialImage)}"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="${esc(title)} — TAMUSNI"><meta name="twitter:description" content="${esc(description)}"><meta name="twitter:image" content="${esc(socialImage)}"><link rel="canonical" href="${canonical}">${hreflangs(current,origin)}<link rel="alternate" hreflang="x-default" href="${origin}/fr/${current}">${jsonLd}<link rel="stylesheet" href="/frontend.css?v=4"><script src="/frontend.js?v=3" defer></script></head><body data-locale="${locale}" data-auth="${session?'true':'false'}"><a class="skip-link" href="#main">${t.explore}</a><header class="site-header" id="site-header"><div class="header-inner"><a class="site-brand" href="${href(locale)}" aria-label="TAMUSNI — ${t.home}"><img src="/brand/${brand}" alt="${rtl?'تاموسني':'TAMUSNI'}" width="190" height="54"></a><div class="header-actions"><label class="sr-only" for="language">Language</label><select id="language" aria-label="Language" data-path="${esc(current)}">${locales.map(l=>`<option value="${l}" ${l===locale?'selected':''}>${l.toUpperCase()}</option>`).join('')}</select><button id="menu-toggle" class="icon-button menu-toggle" type="button" aria-label="${t.menu}" aria-expanded="false" aria-controls="site-menu" title="${t.menu}">${icon('menu')}</button></div><nav id="site-menu" class="site-menu" aria-label="${t.menu}" hidden><a class="home-menu" href="${href(locale)}">${t.home}</a>${nav}<div class="menu-account">${session?`<a href="${href(locale,'mon-espace/')}">${t.dashboard}</a>${session.role==='ADMIN'?'<a href="/admin/">Admin</a>':''}<button id="logout" type="button">${t.logout}</button>`:`<a href="${href(locale,'connexion/')}">${t.login}</a>`}</div></nav></div></header><main id="main" tabindex="-1">${main}</main><footer class="site-footer"><div class="footer-inner"><div class="footer-top"><a href="${href(locale)}" class="footer-brand"><img src="/brand/${brand}" alt="${rtl?'تاموسني':'TAMUSNI'}" width="160" height="46"></a><div class="footer-trust"><strong>${labels.trust}</strong><a href="${href(locale,'a-propos/')}">${labels.about}</a><a href="${href(locale,'methodologie-editoriale/')}">${labels.methodology}</a><a href="${href(locale,'politique-ia/')}">${labels.ai}</a><a href="${href(locale,'politique-corrections/')}">${labels.corrections}</a></div><div class="footer-trust"><strong>${t.contact}</strong><a href="${href(locale,'contact/')}">${labels.contact}</a><a href="mailto:aetbconseil@gmail.com">aetbconseil@gmail.com</a></div></div><div class="footer-bottom"><span>© ${new Date().getUTCFullYear()} TAMUSNI · A&amp;B TECHNOLOGIES</span><nav aria-label="${t.legal}"><a href="${href(locale,'mentions-legales/')}">${t.legal}</a><a href="${href(locale,'confidentialite/')}">${t.privacy}</a><a href="${href(locale,'cookies/')}">${t.cookies}</a><a href="${href(locale,'conditions-utilisation/')}">${labels.terms}</a></nav></div></div></footer><button class="back-top icon-button" id="back-top" type="button" aria-label="${t.back}" title="${t.back}" hidden>${icon('arrow')}</button><div id="toast" class="toast" role="status" aria-live="polite" hidden></div></body></html>`;
}
async function rows(context, locale, where, bindings, sort, limit) {
  const sql=`SELECT c.id,c.slug,c.type,c.title,c.excerpt,c.summary,c.category,c.author_name,c.cover_url,c.published_at,COUNT(DISTINCT v.id) AS views,COALESCE(t.title,e.title) AS localized_title,COALESCE(t.excerpt,e.excerpt) AS localized_excerpt FROM content_items c LEFT JOIN content_views v ON v.content_id=c.id LEFT JOIN content_translations t ON t.content_id=c.id AND t.locale=? LEFT JOIN content_translations_extra e ON e.content_id=c.id AND e.locale=? WHERE c.status='published' AND c.published_at<=? ${where} GROUP BY c.id ORDER BY ${sort} LIMIT ?`;
  const result=await context.env.DB.prepare(sql).bind(locale,locale,new Date().toISOString(),...bindings,limit).all(); return result.results||[];
}
async function home(context,locale,showAds=false) {
  const t=copy[locale]; const [more,popular]=await Promise.all([rows(context,locale,'',[],'c.published_at DESC',12),rows(context,locale,'',[],'views DESC,c.published_at DESC',6)]);
  await localizeRows(context,locale,[...more,...popular]);
  const latest=more.slice(0,3);
  const slides=latest.map((item,i)=>`<article class="hero-slide ${i===0?'is-current':''}" data-slide="${i}" ${i?'inert aria-hidden="true"':''}><div class="hero-image">${image(item,'',i===0)}</div><div class="hero-copy"><span class="eyebrow">${esc(localizedCategory(locale,item.category))} · ${date(item.published_at,locale)}</span><h1><a href="${articleHref(locale,item)}">${esc(storyTitle(locale,item))}</a></h1><p>${esc(storyExcerpt(locale,item))}</p><a class="text-link" href="${articleHref(locale,item)}">${t.read} ${icon('chevron')}</a></div></article>`).join('');
  const popularCards=popular.map((item,i)=>`<article class="popular-card ${i===1?'is-active':''}"><a href="${articleHref(locale,item)}">${image(item)}<span class="eyebrow">${esc(localizedCategory(locale,item.category))}</span><h3>${esc(storyTitle(locale,item))}</h3></a></article>`).join('');
  const ad=showAds?`<aside class="ad-placement" data-ad-slot="mid-page" aria-label="${t.sponsored}"></aside>`:'';
  return `<section class="hero-section" aria-label="${t.latest}"><div class="hero-rail">${slides||`<p class="empty">${t.empty}</p>`}</div>${latest.length>1?`<div class="carousel-controls hero-controls"><button type="button" data-carousel="hero" data-direction="-1" aria-label="Previous">${icon('chevron')}</button><span class="slide-count"><b id="hero-index">01</b> / 0${latest.length}</span><button type="button" data-carousel="hero" data-direction="1" aria-label="Next">${icon('chevron')}</button><button class="pause-button" type="button" data-pause="hero" aria-label="Pause">Ⅱ</button></div>`:''}</section><section class="section-wrap popular-section reveal"><div class="section-heading"><div><span class="eyebrow">TAMUSNI / 01</span><h2>${t.popular}</h2></div><div class="carousel-controls"><button type="button" data-carousel="popular" data-direction="-1" aria-label="Previous">${icon('chevron')}</button><button type="button" data-carousel="popular" data-direction="1" aria-label="Next">${icon('chevron')}</button><button class="pause-button" type="button" data-pause="popular" aria-label="Pause">Ⅱ</button></div></div><div class="popular-track" id="popular-track">${popularCards||`<p class="empty">${t.empty}</p>`}</div></section><section class="section-wrap latest-section reveal"><div class="section-heading"><div><span class="eyebrow">TAMUSNI / 02</span><h2>${t.latest}</h2></div></div><div class="story-grid">${cardList(locale,more)}</div></section>${ad}<section class="newsletter-section reveal"><div class="section-wrap newsletter-inner"><div><span class="eyebrow">TAMUSNI / 03</span><h2>${t.newsletter}</h2><p>${t.weekly}</p></div><form id="newsletter-form"><label for="newsletter-email">${t.email}</label><div class="newsletter-fields"><input type="email" name="email" id="newsletter-email" placeholder="email@example.com" autocomplete="email" required><button type="submit">${t.subscribe}</button></div></form></div></section>`;
}
async function rubric(context,locale,index) {
  const t=copy[locale]; const url=new URL(context.request.url); const q=(url.searchParams.get('q')||'').trim().slice(0,100); const sort=['recent','oldest','popular'].includes(url.searchParams.get('sort'))?url.searchParams.get('sort'):'recent'; const order=sort==='popular'?'views DESC,c.published_at DESC':sort==='oldest'?'c.published_at ASC':'c.published_at DESC';
  const categoryFilter=index===0?"AND c.category IN ('Intelligence','Intelligence artificielle')":"AND c.category=?";
  const candidates=await rows(context,locale,categoryFilter,index===0?[]:[category[index]],order,q?100:24);
  await localizeRows(context,locale,candidates);
  const items=q?candidates.filter(item=>matchesSearch(q,item,locale)).slice(0,24):candidates;
  const title=names[locale][index]; return `<section class="rubric-intro section-wrap reveal"><span class="eyebrow">TAMUSNI / 0${index+1}</span><h1>${title}</h1><p>${t.explore} · ${title}</p></section><section class="section-wrap rubric-content"><form class="rubric-search" method="get" action="${href(locale,sections[index]+'/')}"><label class="sr-only" for="rubric-query">${t.search}</label><span aria-hidden="true">${icon('search')}</span><input id="rubric-query" name="q" value="${esc(q)}" placeholder="${t.searchHint}"><button type="submit" aria-label="${t.search}" title="${t.search}">${icon('search')}</button></form><div class="filter-row"><span>${items.length} ${t.all.toLowerCase()}</span><form method="get"><input type="hidden" name="q" value="${esc(q)}"><label for="sort">${t.explore}</label><select id="sort" name="sort" onchange="this.form.submit()"><option value="recent" ${sort==='recent'?'selected':''}>${t.recent}</option><option value="popular" ${sort==='popular'?'selected':''}>${t.popular}</option><option value="oldest" ${sort==='oldest'?'selected':''}>${t.oldest}</option></select></form></div><div class="story-grid">${cardList(locale,items)}</div></section>`;
}
async function article(context,locale,slug,showAds=false,origin='') {
  const t=copy[locale]; const item=await context.env.DB.prepare("SELECT id,slug,type,title,excerpt,body,summary,category,author_name,cover_url,published_at,updated_at,sponsored,automated,image_disclosure FROM content_items WHERE slug=? AND status='published' AND published_at<=?").bind(slug,new Date().toISOString()).first(); if(!item)return null;
  const translationTable=locale==='es'||locale==='pt'?'content_translations_extra':'content_translations';
  const translationFields=translationTable==='content_translations'?'title,excerpt,body,summary,ai_disclosure':"title,excerpt,body,summary,'' AS ai_disclosure";
  const [translation,sources,stats]=await Promise.all([context.env.DB.prepare(`SELECT ${translationFields} FROM ${translationTable} WHERE content_id=? AND locale=?`).bind(item.id,locale).first(),context.env.DB.prepare('SELECT label,url,publisher,published_at FROM content_sources WHERE content_id=? ORDER BY created_at').bind(item.id).all(),context.env.DB.prepare('SELECT (SELECT COUNT(*) FROM content_views WHERE content_id=?) AS views,(SELECT COUNT(*) FROM content_likes WHERE content_id=?) AS likes').bind(item.id,item.id).first()]);
  const display=await localizeArticle(context,locale,item,translation); const body=display?.body?String(display.body).split(/\n\s*\n/).map(p=>`<p>${esc(p).replace(/\n/g,'<br>')}</p>`).join(''):`<p class="translation-note">${t.unavailable}</p>`;
  const sourceList=(sources.results||[]).map(source=>`<li><a href="${safeUrl(source.url)}" rel="noopener noreferrer" target="_blank">${esc(source.label||source.publisher||source.url)}</a>${source.publisher?`<span>${esc(source.publisher)}${source.published_at?` · ${date(source.published_at,locale)}`:''}</span>`:''}</li>`).join('');
  const categoryIndex=item.category==='Intelligence'?0:category.indexOf(item.category);
  const publicTitle=display?.title||(locale==='fr'?item.title:t.unavailable);
  const ad=showAds?`<aside class="ad-placement" data-ad-slot="article-inline" aria-label="${t.sponsored}"></aside>`:'';
  const format=item.type==='brief'?t.brief:t.articles;
  const disclosure=display?.ai_disclosure||(item.automated?aiDisclosureText(locale):'');
  const main=`<article class="article-page" data-slug="${esc(item.slug)}" data-item-id="${esc(item.id)}" data-title="${esc(publicTitle)}"><header class="article-head section-wrap"><div class="article-kickers"><a class="eyebrow" href="${href(locale,categoryIndex<0?'':sections[categoryIndex]+'/')}">${esc(localizedCategory(locale,item.category))}</a><span class="content-format">${esc(format)}</span>${item.sponsored?`<span class="sponsor-label">${t.sponsored}</span>`:''}</div><h1>${esc(publicTitle)}</h1><p class="article-deck">${esc(display?.excerpt||'')}</p><div class="article-meta"><span>${t.author} · ${esc(item.author_name)}</span><time datetime="${esc(item.published_at)}">${t.published} ${date(item.published_at,locale)}</time><span id="view-count">${Number(stats?.views||0)} ${t.views}</span></div>${disclosure?`<p class="ai-disclosure">${esc(disclosure)}</p>`:''}</header><figure class="article-cover section-wrap">${image(item)}${item.image_disclosure?`<figcaption>${esc(item.image_disclosure)}</figcaption>`:''}</figure><div class="article-body">${body}</div>${ad}<div class="article-actions section-wrap"><button type="button" class="icon-button like-action" aria-label="${t.like}" title="${t.like}">${icon('heart')} <span id="like-count">${Number(stats?.likes||0)}</span></button><button type="button" class="icon-button save-action" aria-label="${t.save}" title="${t.save}">${icon('bookmark')}</button><button type="button" class="share-action icon-button" aria-label="${t.share}" title="${t.share}">${icon('share')}</button></div><section class="article-sources section-wrap"><h2>${t.source}</h2><ul>${sourceList}</ul></section></article>`;
  const structuredData={"@context":"https://schema.org","@type":item.type==='brief'?"NewsArticle":"Article",headline:publicTitle,description:display?.excerpt||'',datePublished:item.published_at,dateModified:item.updated_at||item.published_at,author:{"@type":"Organization",name:"TAMUSNI"},publisher:{"@type":"Organization",name:"TAMUSNI",logo:{"@type":"ImageObject",url:`${origin}/brand/tamusni-latin.png`}},mainEntityOfPage:{"@type":"WebPage","@id":`${origin}/${locale}/articles/${encodeURIComponent(item.slug)}/`},...(item.cover_url?{image:[new URL(item.cover_url,origin).href]}:{})};
  return {main,title:publicTitle,description:display?.excerpt||'',structuredData:[structuredData],imageUrl:item.cover_url||''};
}
function authPage(locale,kind) {
 const t=copy[locale],signup=kind==='inscription'; const fields=signup?`<div class="field-grid"><label>${t.first}<input name="firstName" autocomplete="given-name" required></label><label>${t.last}<input name="lastName" autocomplete="family-name" required></label></div>`:'';
 return `<section class="auth-section section-wrap"><div class="auth-intro"><span class="eyebrow">TAMUSNI / ${t.account}</span><h1>${signup?t.signupTitle:t.loginTitle}</h1><p>${signup?t.explore:t.welcome}</p></div><form class="auth-form" id="${signup?'signup-form':'login-form'}">${fields}<label>${t.email}<input name="email" type="email" autocomplete="email" required></label><label>${t.password}<span class="password-field"><input name="password" type="password" minlength="6" autocomplete="${signup?'new-password':'current-password'}" required><button type="button" class="show-password icon-button" aria-label="${t.passwordShow}" title="${t.passwordShow}">${icon('eye')}</button></span></label>${signup?`${topicChoices(locale,[],true)}<label class="check"><input type="checkbox" name="termsAccepted" required> ${t.terms}</label><label class="check"><input type="checkbox" name="sponsoredEmail"> ${t.sponsor}</label>`:`<button class="text-button" id="forgot-trigger" type="button">${t.forgot}</button>`}<button type="submit" class="primary-button">${signup?t.signupTitle:t.loginTitle}</button><p class="form-error" role="alert" hidden></p><a class="google-button" href="/api/auth/oauth?provider=google&intent=${signup?'signup':'login'}"><img src="/brand/google.png" width="20" height="20" alt="">${t.google}</a><a class="auth-switch" href="${href(locale,signup?'connexion/':'inscription/')}">${signup?t.hasAccount:t.noAccount}</a></form></section>${!signup?`<dialog id="reset-dialog" class="reset-dialog"><form method="dialog"><button class="dialog-close icon-button" value="cancel" aria-label="${t.close}" title="${t.close}">${icon('close')}</button></form><h2>${t.resetTitle}</h2><p>${t.resetInfo}</p><form id="reset-form"><label>${t.email}<input type="email" name="email" autocomplete="email" required></label><div class="dialog-actions"><button type="button" id="reset-cancel">${t.cancel}</button><button type="submit" class="primary-button">${t.send}</button></div><p class="form-error" role="alert" hidden></p></form></dialog>`:''}`;
}
async function dashboard(context,locale,session) {
 const t=copy[locale]; if(!session)return null; const [profile,history,saved,subscriptions]=await Promise.all([context.env.DB.prepare('SELECT id,name,email,preferred_topic,preferred_language,sponsored_email FROM users WHERE id=?').bind(session.sub).first(),context.env.DB.prepare('SELECT c.slug,c.title,c.category,h.last_read_at FROM reading_history h JOIN content_items c ON c.id=h.content_id WHERE h.user_id=? ORDER BY h.last_read_at DESC LIMIT 20').bind(session.sub).all(),context.env.DB.prepare('SELECT item_id,title,url FROM saved_items WHERE user_id=? ORDER BY created_at DESC LIMIT 30').bind(session.sub).all(),context.env.DB.prepare('SELECT topic FROM topic_subscriptions WHERE user_id=? ORDER BY topic').bind(session.sub).all()]);
 const list=(items,fn)=>items.length?`<ul class="dashboard-list">${items.map(fn).join('')}</ul>`:`<p>${t.empty}</p>`;
 const selectedTopics=[...new Set([profile.preferred_topic,...(subscriptions.results||[]).map(item=>item.topic)].filter(Boolean))];
 return `<div class="dashboard-page section-wrap"><div class="rubric-intro"><span class="eyebrow">TAMUSNI / ${t.account}</span><h1>${t.welcome}, ${esc((profile.name||'').split(' ')[0])}</h1></div><div class="dashboard-columns"><section><h2>${t.profile}</h2><form id="profile-form" class="auth-form"><label>${t.first}<input name="name" value="${esc(profile.name)}" required></label><label>${t.email}<input name="email" type="email" value="${esc(profile.email)}" required></label>${topicChoices(locale,selectedTopics,true)}<label class="check"><input type="checkbox" name="sponsoredEmail" ${profile.sponsored_email?'checked':''}>${t.sponsor}</label><button class="primary-button" type="submit">${t.saveChanges}</button><p class="form-error" role="alert" hidden></p></form><details><summary>${t.password}</summary><form id="password-form" class="auth-form"><label>${t.currentPassword}<input type="password" name="currentPassword" required></label><label>${t.newPassword}<input type="password" name="newPassword" minlength="6" required></label><button class="primary-button" type="submit">${t.saveChanges}</button><p class="form-error" role="alert" hidden></p></form></details><details><summary>${t.deleteAccount}</summary><form id="delete-form" class="auth-form"><label>${t.deleteConfirm}<input type="password" name="password" required></label><button class="danger-button" type="submit">${t.deleteAccount}</button><p class="form-error" role="alert" hidden></p></form></details></section><section><h2>${t.favorite}</h2>${list(saved.results||[],i=>`<li>${safeUrl(i.url)?`<a href="${safeUrl(i.url)}">${esc(i.title)}</a>`:esc(i.title)}</li>`)}<h2>${t.history}</h2>${list(history.results||[],i=>`<li><a href="${articleHref(locale,i)}">${esc(i.title)}</a><small>${date(i.last_read_at,locale)}</small></li>`)}</section></div></div>`;
}
